   111  GF_Err meta_box_read(GF_Box *s, GF_BitStream *bs)
   112  {
   113          u64 pos = gf_bs_get_position(bs);
   114          u64 size = s->size;
   115          GF_Err e = gf_isom_box_array_read(s, bs, meta_on_child_box);
   116          /*try to hack around QT files which don't use a full box for meta, rewind 4 bytes*/
   117          if (e && (pos>4) ) {
   118                  gf_bs_seek(bs, pos-4);
   119                  meta_reset(s);
   120                  s->size = size+4;
   121                  e = gf_isom_box_array_read(s, bs, meta_on_child_box);
   122          }
   123          return e;
   124  }
